<script setup lang="ts">
// HR-7c payslip (HR-PLAN 17.2): a frozen snapshot of the locked run, one A4 page, white in every theme (PRINT-1).
// Each person sees their own; opening it is recorded. Generated by KPOne; to confirm with the accountant before real use.
import { Head } from '@inertiajs/vue3';
import { computed } from 'vue';
import { myr } from '@/types/billing';

type Line = {
    kind: string;
    section: string;
    amountSen: number;
    explanation: string;
};
type Totals = Record<
    | 'earnings'
    | 'deduction'
    | 'refund'
    | 'employee'
    | 'employer'
    | 'mtd'
    | 'net',
    number
>;

const props = defineProps<{
    payslip: {
        id: string;
        own: boolean;
        name: string;
        kind: 'regular' | 'adjustment';
        period: string;
        adjusts: string | null;
        group: string;
        payDay: number | null;
        letterhead: {
            clinicName: string;
            legalName: string;
            registration: string | null;
            address: string[];
            contact: string[];
        };
        lines: Line[];
        totals: Totals;
        bank: { name: string; last4: string } | null;
        lockedAt: string;
        issuedOn: string;
    };
}>();

const sections = [
    { key: 'earnings', title: 'Earnings', total: 'earnings' },
    { key: 'deduction', title: 'Deductions', total: 'deduction' },
    { key: 'refund', title: 'Refunds', total: 'refund' },
    { key: 'employee', title: 'Employee contributions', total: 'employee' },
    { key: 'mtd', title: 'MTD (PCB)', total: 'mtd' },
] as const;
const linesFor = (section: string) =>
    props.payslip.lines.filter((l) => l.section === section);
const employer = computed(() => linesFor('employer'));
const title = computed(() =>
    props.payslip.kind === 'adjustment'
        ? `Payslip adjustment · ${props.payslip.adjusts ?? props.payslip.period}`
        : `Payslip · ${props.payslip.period}`,
);
const print = () => window.print();
</script>

<template>
    <Head :title="title" />
    <main
        class="document-print payslip mx-auto max-w-3xl min-w-0 bg-background p-4 text-sm text-foreground sm:p-8 print:bg-white print:text-black"
        data-test="payslip"
    >
        <div
            class="mb-4 flex flex-wrap items-center gap-3 print:hidden"
            data-testid="print-toolbar"
        >
            <button
                type="button"
                class="min-h-11 rounded-md border px-3 py-2 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none lg:min-h-9"
                @click="print"
            >
                Print payslip
            </button>
            <a
                :href="payslip.own ? '/hr/records' : '/hr/payroll?tab=runs'"
                class="inline-flex min-h-11 items-center rounded-md px-3 py-2 underline focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none lg:min-h-9"
                >{{
                    payslip.own
                        ? 'Back to My HR details'
                        : 'Back to payroll runs'
                }}</a
            >
        </div>

        <!-- The same letterhead text block as the other letters (Daniel): the clinic name first and bold, the address on
             one line, then "Tel: …" printed through PrintedPhone on the server. No logo in v1. -->
        <header class="mb-5 border-b pb-4" data-test="payslip-letterhead">
            <p class="text-base font-bold">
                {{ payslip.letterhead.clinicName }}
            </p>
            <p
                v-for="line in payslip.letterhead.address"
                :key="line"
                class="text-xs"
            >
                {{ line }}
            </p>
            <p v-if="payslip.letterhead.contact.length" class="text-xs">
                {{ payslip.letterhead.contact.join(' · ') }}
            </p>
        </header>

        <section class="mb-5 flex flex-wrap items-start justify-between gap-3">
            <div class="min-w-0">
                <h1 class="text-lg font-semibold text-balance">{{ title }}</h1>
                <p class="break-words">{{ payslip.name }}</p>
                <p class="text-xs text-muted-foreground print:text-black">
                    {{ payslip.group
                    }}<template v-if="payslip.payDay">
                        · pay day {{ payslip.payDay }}</template
                    >
                    · issued {{ payslip.issuedOn }}
                </p>
            </div>
            <div class="text-right">
                <p class="text-xs">Net pay</p>
                <p
                    class="text-xl font-bold tabular-nums"
                    data-test="payslip-net"
                >
                    {{ myr(payslip.totals.net) }}
                </p>
                <p v-if="payslip.bank" class="text-xs">
                    Paid to {{ payslip.bank.name }} ending
                    {{ payslip.bank.last4 }}
                </p>
                <p v-else class="text-xs">No bank account on file.</p>
            </div>
        </section>

        <template v-for="s in sections" :key="s.key">
            <section
                v-if="linesFor(s.key).length"
                class="mb-4 break-inside-avoid"
            >
                <h2 class="mb-1 font-semibold">{{ s.title }}</h2>
                <table class="w-full text-sm">
                    <thead class="sr-only">
                        <tr>
                            <th scope="col">Item</th>
                            <th scope="col">Amount</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr
                            v-for="(line, i) in linesFor(s.key)"
                            :key="`${s.key}-${i}`"
                            class="border-t"
                        >
                            <td class="py-1 pr-3 break-words">
                                {{ line.explanation }}
                            </td>
                            <td
                                class="py-1 text-right whitespace-nowrap tabular-nums"
                            >
                                {{ myr(line.amountSen) }}
                            </td>
                        </tr>
                        <tr class="border-t font-medium">
                            <td class="py-1 pr-3">Total</td>
                            <td
                                class="py-1 text-right whitespace-nowrap tabular-nums"
                            >
                                {{ myr(payslip.totals[s.total]) }}
                            </td>
                        </tr>
                    </tbody>
                </table>
            </section>
        </template>

        <section
            class="mb-4 flex items-baseline justify-between border-y py-2 text-base font-bold"
        >
            <span>Net pay</span>
            <span class="tabular-nums">{{ myr(payslip.totals.net) }}</span>
        </section>

        <section v-if="employer.length" class="mb-4 break-inside-avoid">
            <h2 class="mb-1 font-semibold">
                Employer contributions (information)
            </h2>
            <table class="w-full text-sm">
                <thead class="sr-only">
                    <tr>
                        <th scope="col">Item</th>
                        <th scope="col">Amount</th>
                    </tr>
                </thead>
                <tbody>
                    <tr
                        v-for="(line, i) in employer"
                        :key="`employer-${i}`"
                        class="border-t"
                    >
                        <td class="py-1 pr-3 break-words">
                            {{ line.explanation }}
                        </td>
                        <td
                            class="py-1 text-right whitespace-nowrap tabular-nums"
                        >
                            {{ myr(line.amountSen) }}
                        </td>
                    </tr>
                </tbody>
            </table>
        </section>

        <p class="mt-6 text-xs">
            Generated by KPOne. To confirm with the clinic's accountant before
            real use. Synthetic data only.
        </p>
    </main>
</template>

<style>
@page {
    size: A4;
    margin: 15mm;
}
@media print {
    .payslip {
        max-width: none;
        padding: 0;
        background: white;
        color: black;
    }
    .payslip tr,
    .payslip section {
        break-inside: avoid;
    }
    .payslip td {
        overflow-wrap: anywhere;
    }
}
</style>
